export function FigmaGradientIcon({
  name,
  className = "fg-grad-ic",
  size = 24,
}: {
  name: string
  className?: string
  size?: number
}) {
  const body = GRADIENT_SVGS[name] || GRADIENT_SVGS["bao-cao"]
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 32 32"
      fill="none"
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: body }}
    />
  )
}

