export function FigmaTabIcon({
  name,
  active = false,
  className = "fg-tab-ic",
  size = 24,
}: {
  name: "trang-chu" | "nghiep-vu" | "bao-cao" | "khac"
  active?: boolean
  className?: string
  size?: number
}) {
  const key = active ? `${name}-active` : name
  const body = TAB_SVGS[key] || TAB_SVGS[name] || TAB_SVGS["trang-chu"]
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: body }}
    />
  )
}

