export function FigmaMobileIcon({
  name,
  className = "fg-mob-ic",
  size = 24,
}: {
  name: string
  className?: string
  size?: number
}) {
  const iconKey = MOBILE_ICON_MAP[name] || name
  const body = MOBILE_SVGS[iconKey]
  if (!body) return null
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: body }}
    />
  )
}

